-- The parts of the Blend IQ database that online booking requests touch, as
-- deployed after the app's 20261117120000_client_identities migration.
-- Mirrors blend_iq/supabase/tests/fixtures/payment_deployed_schema.sql plus
-- that migration. Test doubles only; no customer data.
create role anon;
create role authenticated;
create role authenticator;
create role service_role bypassrls;
grant anon, authenticated, service_role to authenticator;

-- Supabase's API roles can reach every table in public (RLS decides which
-- rows) and, by default, execute every new function.
grant usage on schema public to anon, authenticated, service_role;
alter default privileges in schema public
  grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public
  grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema public
  grant execute on functions to anon, authenticated, service_role;

create schema auth;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql as $$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;

create table public."BookingProfiles"(
  id bigint generated by default as identity,
  slug text primary key,
  user_id uuid references auth.users(id),
  is_enabled boolean default false
);

create table public."Identities"(
  identity_id uuid default gen_random_uuid() primary key,
  user_id uuid not null default auth.uid()
    references auth.users(id) on update cascade on delete cascade,
  first_name text,
  last_name text,
  birthday text,
  is_client boolean,
  client_id bigint,
  created_at timestamp with time zone default now() not null
);
create table public."IdentityContacts"(
  contact_id bigint generated by default as identity primary key,
  identity_id uuid not null unique
    references public."Identities"(identity_id) on update cascade on delete cascade,
  phone text,
  email text,
  instagram text,
  facebook text,
  prefered_method text,
  created_at timestamp with time zone default now() not null
);
create table public."IdentityPreferences"(
  preference_id bigint generated by default as identity primary key,
  identity_id uuid not null unique
    references public."Identities"(identity_id) on update cascade on delete cascade,
  send_creation boolean default false,
  send_cancellation boolean default false,
  send_reminder boolean default false,
  reminder_lead bigint default 0,
  created_at timestamp with time zone default now() not null
);
create table public."IdentitySMSConsent"(
  consent_id bigint generated by default as identity primary key,
  identity_id uuid not null unique
    references public."Identities"(identity_id) on update cascade on delete cascade,
  consent_status boolean default false,
  updated_at timestamp with time zone,
  created_at timestamp with time zone default now() not null
);

alter table public."Identities" enable row level security;
alter table public."IdentityContacts" enable row level security;
alter table public."IdentityPreferences" enable row level security;
alter table public."IdentitySMSConsent" enable row level security;
create policy "Owners manage their identities" on public."Identities"
  for all to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);
create policy "Owners manage identity contacts" on public."IdentityContacts"
  for all to authenticated
  using (identity_id in (select i.identity_id from public."Identities" i
    where i.user_id = (select auth.uid())))
  with check (identity_id in (select i.identity_id from public."Identities" i
    where i.user_id = (select auth.uid())));
create policy "Owners manage identity preferences" on public."IdentityPreferences"
  for all to authenticated
  using (identity_id in (select i.identity_id from public."Identities" i
    where i.user_id = (select auth.uid())))
  with check (identity_id in (select i.identity_id from public."Identities" i
    where i.user_id = (select auth.uid())));
create policy "Owners manage identity SMS consent" on public."IdentitySMSConsent"
  for all to authenticated
  using (identity_id in (select i.identity_id from public."Identities" i
    where i.user_id = (select auth.uid())))
  with check (identity_id in (select i.identity_id from public."Identities" i
    where i.user_id = (select auth.uid())));

create table public."Appointments"(
  appointment_id bigint generated by default as identity primary key,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid(),
  appointment_date date not null,
  appointment_start_time time without time zone not null,
  client_name text,
  services text,
  formula text,
  appointment_end_time time without time zone,
  client_id bigint,
  price double precision default '0'::double precision,
  notes text,
  status text,
  stylist_slug text,
  denial_reason text,
  client_phone text,
  client_email text,
  send_creation_sms boolean,
  is_online_booking boolean default false not null,
  identity_id uuid references public."Identities"(identity_id)
);

create table public."ReminderJobs"(
  id uuid default gen_random_uuid() primary key,
  appointment_id bigint not null,
  run_at timestamp with time zone not null,
  status text not null,
  created_at timestamp with time zone default now() not null,
  message_type text,
  message_body text
);

-- Stylist push notifications for new requests (20261111033008), without the
-- HTTP wake-up call.
create schema booking_push;
create table booking_push.devices(
  id uuid default gen_random_uuid() primary key,
  user_id uuid not null references auth.users(id) on delete cascade
);
create table booking_push.deliveries(
  appointment_id bigint not null
    references public."Appointments"(appointment_id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  device_id uuid not null references booking_push.devices(id) on delete cascade
);
create function booking_push.queue_request()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into booking_push.deliveries (appointment_id, user_id, device_id)
  select new.appointment_id, p.user_id, d.id
  from public."BookingProfiles" p
  join booking_push.devices d on d.user_id = p.user_id
  where p.slug = new.stylist_slug
    and p.is_enabled is true
    and (new.user_id is null or new.user_id = p.user_id);
  return new;
end;
$$;
create trigger queue_booking_request_push
  after insert on public."Appointments"
  for each row
  when (new.status = 'requested' and new.is_online_booking is true)
  execute function booking_push.queue_request();
